using Microsoft.AspNetCore.Mvc;
using System.IO;
using System.IO.Compression;
using Microsoft.AspNetCore.Http;

namespace FileUploadService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ArchiveController : ControllerBase
    {
        private readonly string _extractionRoot = "/var/app/uploads/extracted";
        private readonly string _staticAssetsPath = "/var/app/wwwroot/js";

        /// <summary>
        /// Accepts a ZIP archive and extracts plugin assets for the frontend.
        /// Plugin JS files are referenced in the layout with integrity attributes.
        /// </summary>
        [HttpPost("upload-plugin")]
        [RequestSizeLimit(50_000_000)]
        public async Task<IActionResult> UploadPlugin(IFormFile archive)
        {
            if (archive == null || archive.Length == 0)
                return BadRequest("No file provided");

            if (!archive.FileName.EndsWith(".zip", StringComparison.OrdinalIgnoreCase))
                return BadRequest("Only ZIP files accepted");

            var tempPath = Path.GetTempFileName();
            try
            {
                using (var stream = new FileStream(tempPath, FileMode.Create))
                {
                    await archive.CopyToAsync(stream);
                }

                var extractedFiles = new List<string>();
                using (var zip = ZipFile.OpenRead(tempPath))
                {
                    foreach (var entry in zip.Entries)
                    {
                        // Skip directories
                        if (string.IsNullOrEmpty(entry.Name))
                            continue;

                        // Construct destination path
                        var destinationPath = Path.Combine(_extractionRoot, entry.FullName);

                        // Ensure parent directory exists
                        var parentDir = Path.GetDirectoryName(destinationPath);
                        if (!Directory.Exists(parentDir))
                            Directory.CreateDirectory(parentDir);

                        // Extract the file
                        entry.ExtractToFile(destinationPath, overwrite: true);
                        extractedFiles.Add(entry.FullName);
                    }
                }

                // Copy JS files to static assets directory for serving
                var jsFiles = extractedFiles.Where(f => f.EndsWith(".js")).ToList();
                foreach (var jsFile in jsFiles)
                {
                    var src = Path.Combine(_extractionRoot, jsFile);
                    var dest = Path.Combine(_staticAssetsPath, Path.GetFileName(jsFile));
                    if (System.IO.File.Exists(src))
                    {
                        System.IO.File.Copy(src, dest, overwrite: true);
                    }
                }

                return Ok(new { 
                    message = "Plugin extracted successfully",
                    files = extractedFiles,
                    jsAssets = jsFiles.Select(Path.GetFileName)
                });
            }
            finally
            {
                if (System.IO.File.Exists(tempPath))
                    System.IO.File.Delete(tempPath);
            }
        }

        /// <summary>
        /// Lists currently installed plugin assets
        /// </summary>
        [HttpGet("plugins")]
        public IActionResult ListPlugins()
        {
            if (!Directory.Exists(_extractionRoot))
                return Ok(new { plugins = Array.Empty<string>() });

            var files = Directory.GetFiles(_extractionRoot, "*", SearchOption.AllDirectories)
                .Select(f => Path.GetRelativePath(_extractionRoot, f))
                .ToList();

            return Ok(new { plugins = files });
        }
    }
}

